def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """

    # Validate inputs
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not isinstance(fields, list):
        raise TypeError("fields must be a list")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dictionary")

    # Create a dictionary to hold the field definitions
    namespace = {
        "__annotations__": {field: "typing.Any" for field in fields}
    }

    # dynamically create the subclass using types.new_class
    subclass = types.new_class(name, (object,), {}, lambda ns: ns.update(namespace))

    # Add methods to the subclass
    def from_coordinates(self, x, y, srid):
        if srid not in srid_map:
            raise ValueError(f"Invalid SRID: {srid}")
        return subclass(x, y, srid)

    subclass.from_coordinates = from_coordinates

    return subclass

