from typing import Callable, Any, Tuple
from functools import wraps, partial
import time

def _hashable(item):
    try:
        hash(item)
        return True
    except TypeError:
        return False

def _make_key(func, args, kwds, typed=False):
    if typed and not _hashable(args):
        args = tuple(type(v) for v in args)
    if typed and not _hashable(frozenset(kwds.items())):
        kwds = frozenset(kwds.items())
    return func, args, kwds

def _make_ticker(ttl, timer):
    end = timer() + ttl
    def ticker():
        return end > timer()
    return ticker

class TTLCache:
    def __init__(self, maxsize, ttl, timer, typed):
        self.cache = {}
        self.ttl = ttl
        self.timer = timer
        self.typed = typed
        self.access_times = {}
        self.maxsize = maxsize

    def _cleanup(self):
        now = self.timer()
        to_delete = []
        for key, access_time in self.access_times.items():
            if access_time < now:
                to_delete.append(key)
        for key in to_delete:
            del self.cache[key]
            del self.access_times[key]

    def __getitem__(self, key):
        self._cleanup()
        return self.cache[key]

    def __setitem__(self, key, value):
        self._cleanup()
        if len(self.cache) >= self.maxsize:
            least_recent = min(self.access_times, key=self.access_times.get)
            del self.cache[least_recent]
            del self.access_times[least_recent]
        self.cache[key] = value
        self.access_times[key] = self.timer()

    def __contains__(self, key):
        self._cleanup()
        return key in self.cache

def ttl_cache(maxsize: int = 128, ttl: int = 600, timer: Callable[[], float] = time.monotonic, typed: bool = False) -> Callable[[Callable], Callable]:
    def decorator(func: Callable) -> Callable:
        ticker = _make_ticker(ttl, timer)
        cache = TTLCache(maxsize, ttl, timer, typed)

        @wraps(func)
        def wrapper(*args: Any, **kwds: Any) -> Any:
            key = _make_key(func, args, kwds, typed)
            if key not in cache or not ticker():
                result = func(*args, **kwds)
                cache[key] = result
            return cache[key]

        return wrapper

    return decorator

