def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    visited = set()
    minimal_classes = []

    def dfs(cls):
        if cls in visited:
            return
        visited.add(cls)
        for b in cls.__bases__:
            dfs(b)
        minimal_classes.insert(0, cls)

    for cls in classes:
        dfs(cls)

    return minimal_classes

