def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    default_observer_schema = {}

    for manifest in app.spec.manifest:
        resource_type = manifest.get("apiVersion", "unknown") + "/" + manifest.get("kind", "unknown")
        if resource_type not in default_observer_schema:
            default_observer_schema[resource_type] = {
                "type": "object",
                "properties": {},
                "additionalProperties": False
            }

        # Add default properties for each field in the resource
        for key, value in manifest.get("spec", {}).items():
            if key not in default_observer_schema[resource_type]["properties"]:
                if isinstance(value, dict):
                    default_observer_schema[resource_type]["properties"][key] = {
                        "type": "object",
                        "properties": {}
                    }
                elif isinstance(value, list):
                    default_observer_schema[resource_type]["properties"][key] = {
                        "type": "array",
                        "items": {}
                    }
                else:
                    default_observer_schema[resource_type]["properties"][key] = {
                        "type": type(value).__name__
                    }

    return default_observer_schema

