def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not fixity:
        raise ValueError("Fixity block cannot be empty")

    allowed_algorithms = {'sha256', 'sha512'}
    for entry in fixity:
        if 'hash' not in entry or 'filename' not in entry:
            raise ValueError("Fixity entry must contain 'hash' and 'filename' keys")
        if entry['hash'].split('=', 1)[0] not in allowed_algorithms:
            raise ValueError("Unsupported hash algorithm: {}".format(entry['hash'].split('=', 1)[0]))

    referenced_files = {entry['filename'] for entry in fixity}
    if not referenced_files.issubset(manifest_files):
        raise ValueError("The fixity block references files not listed in the manifest")

