def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(expr):
        if expr.is_binary():
            left, op, right = expr.left, expr.op, expr.right
            if op == '&':
                if left == right:
                    return left
                elif right.is_binary() and right.op == '|':
                    if left == right.left or left == right.right:
                        return left
            elif op == '|':
                if left == right:
                    return left
                elif right.is_binary() and right.op == '&':
                    if left == right.left or left == right.right:
                        return left
        elif expr.is_unary():
            if expr.op == '~':
                left = expr.child
                if left.is_binary():
                    if left.op == '|':
                        negleft = ~left.left
                        if negleft == left.right:
                            return expr.child
                        elif left.left == negleft:
                            return left.right
                    elif left.op == '&':
                        negleft = ~left.left
                        if negleft == left.right:
                            return expr.child
                        elif left.left == negleft:
                            return left.right
        return expr

    def apply_negative_absorption(expr):
        if expr.is_binary():
            left, op, right = expr.left, expr.op, expr.right
            if op == '&':
                if right.is_binary() and right.op == '|':
                    negright = ~right.right
                    if negright == right.left:
                        return expr.left & right.right
                    elif right.left == negright:
                        return expr.left & right.left
            elif op == '|':
                if right.is_binary() and right.op == '&':
                    negright = ~right.left
                    if negright == right.right:
                        return expr.left | right.right
                    elif right.left == negright:
                        return expr.left | right.left
        return expr

    new_args = []
    for expr in args:
        new_expr = expr.copy()
        new_expr = apply_absorption(new_expr)
        new_expr = apply_negative_absorption(new_expr)
        new_args.append(new_expr)
    return new_args

