def render(pieces, style):
    """Render the given version pieces into the requested style."""

    if not pieces:
        raise ValueError("No pieces provided for rendering")

    if style not in ['html', 'json', 'xml']:
        raise ValueError("Invalid style requested: {0}".format(style))

    if style == 'html':
        rendered_output = "<div>"
        for piece in pieces:
            rendered_output += str(piece)
        rendered_output += "</div>"
    elif style == 'json':
        rendered_output = json.dumps(pieces)
    elif style == 'xml':
        rendered_output = "<output>"
        for piece in pieces:
            rendered_output += "<piece>" + str(piece) + "</piece>"
        rendered_output += "</output>"

    return rendered_output

