def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).

    :param commands: A list of commands to run.
    :type commands: list

    :param args: Arguments for the commands.
    :type args: list or None

    :param cwd: Current working directory for the command(s).
    :type cwd: str or None

    :param verbose: Whether to print verbose output.
    :type verbose: bool

    :param hide_stderr: Whether to hide stderr.
    :type hide_stderr: bool

    :param env: Environment variables for the command(s).
    :type env: dict or None
    """
    import subprocess

    for command in commands:
        if verbose:
            print(f"Running command: {command}")

        if args:
            command_with_args = [command] + args
        else:
            command_with_args = command

        try:
            if hide_stderr:
                output = subprocess.check_output(command_with_args, cwd=cwd, stderr=subprocess.DEVNULL, env=env)
            else:
                output = subprocess.check_output(command_with_args, cwd=cwd, env=env, stderr=subprocess.STDOUT)

            if verbose and output:
                print(output.decode())

        except subprocess.CalledProcessError as e:
            if verbose:
                print(f"Error running command: {command}")
                print(e.output.decode())
            raise

