def parse_frequency(frequency):
    """Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None or frequency.lower() == "always":
        return None

    frequency = frequency.lower().strip()
    units_map = {
        "sec": "seconds", "secs": "seconds", "second": "seconds", "seconds": "seconds",
        "min": "minutes", "mins": "minutes", "minute": "minutes", "minutes": "minutes",
        "hr": "hours", "hrs": "hours", "hour": "hours", "hours": "hours",
        "day": "days", "days": "days",
        "wk": "weeks", "wks": "weeks", "week": "weeks", "weeks": "weeks",
        "mon": "months", "mons": "months", "month": "months", "months": "months",
        "yr": "years", "yrs": "years", "year": "years", "years": "years"
    }

    for unit, attr in units_map.items():
        if frequency.endswith(unit):
            try:
                number = int(frequency.replace(unit, '').strip())
                return getattr(datetime.timedelta, attr)(number)
            except ValueError:
                raise ValueError(f"Invalid frequency: {frequency}")

    raise ValueError(f"Invalid frequency: {frequency}")

