def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not callable(getattr(candidate, iface.__name__, None)):
        return False

    if tentative:
        return True

    for method_name in iface.__dict__:
        if not method_name.startswith("__"):
            method = getattr(iface, method_name)
            candidate_method = getattr(candidate, method_name, None)

            if not callable(candidate_method) or not method.__code__.co_argcount == candidate_method.__code__.co_argcount:
                return False

    return True

