import json
from xml.etree import ElementTree as ET
from typing import Dict, Optional

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try parsing as JSON
        data = json.loads(document)
        if "links" in data:
            parsed_data = {link["rel"]: link["href"] for link in data["links"]}
            return parsed_data
    except json.JSONDecodeError:
        pass  # Fall back to parsing as XRD

    try:
        # Parse as XRD
        root = ET.fromstring(document)
        links = []
        for link in root.findall(".//{http://docs.oasis-open.org/ns/xri/xrd/1.0}Link"):
            rel = link.attrib.get("rel")
            href = link.attrib.get("href")
            if rel and href:
                links.append({"rel": rel, "href": href})
        parsed_data = {link["rel"]: link["href"] for link in links}
        return parsed_data
    except ET.ParseError:
        pass  # Return None if neither JSON nor XRD is valid

    return None

