    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            raise ValueError('Unable to resolve default for non-Option type')

        # If there is a default set, add it to the defaults dictionary
        if not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default

        # If we have a dict option, build the defaults for its scheme.
        # If any defaults exist, use them.
        if isinstance(arg, DictOption):
            if arg.scheme:
                b = arg.scheme.build_defaults()
                if b:
                    defaults[arg.name] = b

        # Resolve value from spec if provided
        if arg in self.spec:
            defaults[arg.name] = self.spec[arg]

    return defaults

