import json

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    if not os.path.exists(plugin_dir):
        raise FileNotFoundError(f"The directory {plugin_dir} does not exist")

    spec_file_path = os.path.join(plugin_dir, 'spec.json')
    if not os.path.exists(spec_file_path):
        raise FileNotFoundError(f"The spec.json file does not exist in directory {plugin_dir}")

    with open(spec_file_path, 'r') as file:
        spec_data = json.load(file)

    flat_dict = {}
    for key, value in spec_data.items():
        if isinstance(value, dict):
            for sub_key, sub_value in value.items():
                flat_dict[f"{key}.{sub_key}"] = sub_value
        else:
            flat_dict[key] = value

    return flat_dict

